"""Synthetic full-matrix tests; no real NOAA scores are generated by this file."""

from __future__ import annotations

from dataclasses import replace
from datetime import UTC, datetime, timedelta

import numpy as np
import pytest

from apps.ocean.reeftrace_ocean import kalman_diagnostic as diagnostic
from apps.ocean.reeftrace_ocean.benchmark import SphericalLocalFrame
from apps.ocean.reeftrace_ocean.data import DrifterRecord


def records():
    """Invented constant-motion SI tracks using the required identity labels only."""
    frame, start = SphericalLocalFrame(0, 0), datetime(2020, 1, 1, tzinfo=UTC)
    result = {}
    for index, identifier in enumerate(diagnostic.DRIFTER_IDS):
        rows = []
        for hour in range(24):
            lat, lon = frame.to_latlon(np.array([(.1 + index * .03) * hour * 3600, .01 * hour * 3600]))
            rows.append(DrifterRecord(identifier, start + timedelta(hours=hour), lat, lon, 0, 0, 0, 0))
        result[identifier] = rows
    return result


def test_synthetic_helper_keeps_unverified_origin_and_exact_complete_matrix():
    report = diagnostic.diagnostic_from_records(records())
    assert report["data_origin"] == "UNVERIFIED_RECORDS"
    assert report["status"] == "COMPLETED"
    assert report["coverage"]["attempted_outcomes"] == report["coverage"]["scored_outcomes"] == 120
    assert report["coverage"]["planned_outcomes"] == 180
    assert report["coverage"]["unique_observed_intervals"] == 24
    assert [row["id"] for row in report["models"]] == list(diagnostic.MODEL_IDS)
    assert all(len(model["predictions"]) == 6 for group in report["groups"] for model in group["models"])
    assert report["parameter_fitting_performed"] is False
    assert report["automatic_model_promotion"] is False


def test_all_twenty_forecasts_exist_before_any_guarded_future_coordinate_is_read(monkeypatch):
    values, completed = records(), []
    original = diagnostic._one_forecast
    def tracked(*args):
        result = original(*args)
        completed.append(True)
        return result
    monkeypatch.setattr(diagnostic, "_one_forecast", tracked)

    class Future:
        def __init__(self, row):
            self.row = row
            self.drifter_id, self.time_utc = row.drifter_id, row.time_utc

        @property
        def latitude_deg(self):
            assert len(completed) == 20, "Future latitude was read before every model existed"
            return self.row.latitude_deg

        @property
        def longitude_deg(self):
            assert len(completed) == 20, "Future longitude was read before every model existed"
            return self.row.longitude_deg

    guarded = {key: [*rows[:18], *(Future(row) for row in rows[18:])] for key, rows in values.items()}
    assert diagnostic.diagnostic_from_records(guarded)["status"] == "COMPLETED"
    assert len(completed) == 20


def test_changing_future_positions_changes_scores_but_never_prepared_predictions():
    values = records()
    before = diagnostic.diagnostic_predictions(values)
    report = diagnostic.diagnostic_from_records(values)
    for identifier, rows in values.items():
        values[identifier] = [*rows[:18], *(replace(row, latitude_deg=row.latitude_deg + .001) for row in rows[18:])]
    after = diagnostic.diagnostic_predictions(values)
    changed = diagnostic.diagnostic_from_records(values)
    for identifier in diagnostic.DRIFTER_IDS:
        assert before[identifier]["models"] == after[identifier]["models"]
    assert report["models"] != changed["models"]


def test_one_failed_track_retains_six_null_outcomes_and_withholds_all_common_metrics(monkeypatch):
    original, failed = diagnostic._one_forecast, []
    def fail_one(model_id, *args):
        if model_id == "kalman_cv" and not failed:
            failed.append(True)
            raise ValueError("Synthetic injected numerical failure")
        return original(model_id, *args)
    monkeypatch.setattr(diagnostic, "_one_forecast", fail_one)
    report = diagnostic.diagnostic_from_records(records())
    assert report["status"] == "INCOMPLETE_OUTCOMES"
    assert report["coverage"]["scored_outcomes"] == 114 and report["coverage"]["failed_outcomes"] == 6
    assert all(row["metrics"] is None for row in report["models"])
    assert report["uncertainty"]["fraction_ranges"] is None
    failed_track = report["groups"][0]["models"][4]
    assert failed_track["status"] == "FAILED" and failed_track["forecast_anchor"] is None
    assert all(row["status"] == "FAILED" and row["position_error_m"] is None
               and row["position_covariance_m2"] is None and row["ellipse_hits"] is None
               for row in failed_track["predictions"])
    assert report["uncertainty"]["per_drifter"][0]["scored_count"] == 0
    assert report["uncertainty"]["per_drifter"][0]["nominal90_hit_fraction"] is None


def test_observation_predictive_ellipse_uses_position_covariance_plus_assumed_R():
    report = diagnostic.diagnostic_from_records(records())
    for group in report["groups"]:
        for index, row in enumerate(group["models"][4]["predictions"]):
            covariance = np.array(row["position_covariance_m2"])
            observed_covariance = np.array(row["observation_covariance_m2"])
            np.testing.assert_allclose(observed_covariance - covariance, 10000 * np.eye(2))
            actual = group["heldout_track"][index]
            residual = np.array([row["x_m"] - actual["x_m"], row["y_m"] - actual["y_m"]])
            score = residual @ np.linalg.solve(observed_covariance, residual)
            assert row["ellipse_hits"] == {key: score <= threshold for key, threshold in diagnostic.CHI2.items()}
    assert report["calibrated_probability"] is False


def test_wrong_group_duplicate_hour_and_non_utc_input_are_not_silently_repaired():
    values = records()
    with pytest.raises(ValueError):
        diagnostic.diagnostic_predictions({"wrong-id": values[diagnostic.DRIFTER_IDS[0]]})
    key = diagnostic.DRIFTER_IDS[0]
    values[key][20] = replace(values[key][20], time_utc=values[key][19].time_utc)
    with pytest.raises(ValueError, match="hourly UTC"):
        diagnostic.diagnostic_predictions(values)
    values = records()
    values[key][0] = replace(values[key][0], time_utc=values[key][0].time_utc.replace(tzinfo=None))
    with pytest.raises(ValueError, match="hourly UTC"):
        diagnostic.diagnostic_predictions(values)


def test_reference_comparison_tolerates_roundoff_but_never_counts_types_or_material_changes():
    diagnostic._same_reference({"x": 729.3650752198894}, {"x": 729.365075219436})
    for actual, frozen in [(True, 1), (120, 119), ([1], [1, 2]), ({"id": "wrong"}, {"id": "kalman"}),
                            (729.37, 729.36), (float("nan"), 1.0)]:
        with pytest.raises(ValueError):
            diagnostic._same_reference(actual, frozen)
